                .thenWaitUntil(() -> {
                    helper.assertValueEqual(core.fertilizer().available(), 100, "fertilizer stored");
                    helper.assertValueEqual(meCount(helper, me, Items.BONE_MEAL), 0L, "bone meal left in ME");
                })
                .thenSucceed();
    }
