# /// script
# requires-python = ">=3.14"
# dependencies = ["pillow"]
# ///
"""Builds the 16x16 block textures for Modular Planters from ATE's art, plus a contact sheet."""
from pathlib import Path
from PIL import Image, ImageDraw

ATE = Path("/Users/sweetjp/DEV/git_repos/minecraft-mods/AgritechEvolved/src/main/resources/assets/agritechevolved/textures/block")
OUT = Path("/Users/sweetjp/DEV/git_repos/minecraft-mods/ate-planter-multiblock/src/main/resources/assets/modular_planters/textures/block")
SHEET = Path.home() / "tmp/2026-10-29-planter-textures/contact-sheet.png"
BORDER = (0x20, 0x26, 0x2A, 255)

def load(name):
    return Image.open(ATE / f"{name}.png").convert("RGBA")

def face(name, box):
    return load(name).crop(box).resize((16, 16), Image.NEAREST)

def whole(name):
    return load(name)

def core(base_box, panes_box):
    img = face("box", base_box)
    img.alpha_composite(face("dome_panes", panes_box))
    ring = face("dome_frame", (0, 0, 16, 16))
    for i in range(1, 15):
        for xy in ((i, 1), (i, 14), (1, i), (14, i)):
            img.putpixel(xy, ring.getpixel(xy))
    return img

# name -> (image, source description)
TEXTURES = {
    "core_side": (lambda: core((20, 0, 44, 16), (0, 0, 10, 14)), "box.png (20,0,44,16) + dome_panes.png (0,0,10,14) + dome_frame.png (0,0,16,16) ring at offset 1"),
    "core_top": (lambda: core((0, 0, 20, 20), (10, 0, 20, 14)), "box.png (0,0,20,20) + dome_panes.png (10,0,20,14) + dome_frame.png (0,0,16,16) ring at offset 1"),
    "power_side": (lambda: whole("capacitor_t3_side"), "capacitor_t3_side.png whole"),
    "power_top": (lambda: whole("capacitor_top"), "capacitor_top.png whole"),
    "power_bottom": (lambda: whole("capacitor_bottom"), "capacitor_bottom.png whole"),
    "fertilizer_side": (lambda: face("fertilizer_spreader_hopper", (12, 0, 28, 16)), "fertilizer_spreader_hopper.png (12,0,28,16)"),
    "fertilizer_top": (lambda: face("hopper", (0, 0, 14, 14)), "hopper.png (0,0,14,14)"),
    "export_side": (lambda: face("silo_side", (0, 0, 16, 16)), "silo_side.png (0,0,16,16)"),
    "export_top": (lambda: face("silo_bottom", (0, 0, 12, 12)), "silo_bottom.png (0,0,12,12)"),
    "planter_side": (lambda: face("box", (20, 0, 44, 16)), "box.png (20,0,44,16)"),
    "planter_side_on": (lambda: face("box_on", (20, 0, 44, 16)), "box_on.png (20,0,44,16)"),
    "planter_top": (lambda: whole("infused_farmland_top"), "infused_farmland_top.png whole"),
    "frame_side": (lambda: whole("capacitor_sides"), "capacitor_sides.png whole"),
}

def with_border(img):
    d = ImageDraw.Draw(img)
    d.rectangle((0, 0, 15, 15), outline=BORDER)
    return img

def main():
    OUT.mkdir(parents=True, exist_ok=True)
    sources = [p.read_bytes() for p in ATE.glob("*.png")]
    rendered = {}
    for name, (build, desc) in TEXTURES.items():
        img = with_border(build().convert("RGBA"))
        assert img.size == (16, 16), name
        assert img.getchannel("A").getextrema() == (255, 255), f"{name} has transparent pixels"
        path = OUT / f"{name}.png"
        img.save(path)
        assert path.read_bytes() not in sources, f"{name} is byte-identical to an ATE texture"
        rendered[name] = img
        print(f"{name}: {desc}")

    cell, label_h, cols = 128, 14, 5
    rows = -(-len(rendered) // cols)
    sheet = Image.new("RGBA", (cols * (cell + 8) + 8, rows * (cell + label_h + 8) + 8), (40, 40, 40, 255))
    d = ImageDraw.Draw(sheet)
    for i, (name, img) in enumerate(rendered.items()):
        x = 8 + (i % cols) * (cell + 8)
        y = 8 + (i // cols) * (cell + label_h + 8)
        d.text((x, y), name, fill=(255, 255, 255, 255))
        sheet.alpha_composite(img.resize((cell, cell), Image.NEAREST), (x, y + label_h))
    sheet.save(SHEET)

main()

